#include "scene_translucent_order_candidate.h"
#include <iostream>
struct Model {struct {bool visible=true;}model;std::vector<float>vertices;};
int main(){try{std::vector<Model>models{{{true},{1,1,1,3,3,3}},{{true},{4,4,4}}};std::vector<ModelRenderInputsCandidate>inputs(2);for(auto&input:inputs){input.materials.resize(1);input.materials[0].translucent=true;}inputs[0].indices={0,1,2,3,4,5};inputs[0].ranges={{0,3,0},{3,3,0}};inputs[1].indices={0,1,2};inputs[1].ranges={{0,3,0}};auto depth=[](float value){return double(value);};auto order=sceneTranslucentOrderCandidate(models,inputs,depth);if(order.size()!=3||order[0].model!=1||order[1].range!=1||order[2].range!=0)throw std::runtime_error("cross-model order");models[1].vertices={3,3,3};order=sceneTranslucentOrderCandidate(models,inputs,depth);if(order[0].model!=0||order[0].range!=1||order[1].model!=1)throw std::runtime_error("stable tie");models[1].model.visible=false;if(sceneTranslucentOrderCandidate(models,inputs,depth).size()!=2)throw std::runtime_error("hidden model");inputs[0].indices[0]=999;bool rejected=false;try{sceneTranslucentOrderCandidate(models,inputs,depth);}catch(std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("bad index accepted");std::cout<<"scene transparency order passed cross_model=1 stable_ties=1 hidden_models=excluded invalid_index=rejected GPU_integration=unfinished\n";return 0;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
